const laptop=document.getElementById('laptop-dialog');const osDesktop=document.getElementById('os-desktop');const osWindow=document.getElementById('os-window');const appContent=document.getElementById('os-app-content');let currentApp=null;let scratchText='';let paintColor='#2954d8';let paintStrokes=[];let activeStroke=null;let paintResizeObserver=null;let terminalLines=['Welcome to fouadOS. A tiny terminal for curious people.','Type help to explore, or tap a command below.'];
document.getElementById('open-laptop').onclick=()=>{laptop.showModal();updateClock()};document.getElementById('close-laptop').onclick=()=>laptop.close();laptop.addEventListener('click',e=>{if(e.target===laptop){const r=laptop.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)laptop.close()}});
function updateClock(){document.getElementById('os-clock').textContent=new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}setInterval(()=>{if(laptop.open)updateClock()},30000);
function wallpaper(){const n=(Number(osDesktop.dataset.wallpaper)+1)%3;osDesktop.dataset.wallpaper=n;document.getElementById('os-wallpaper').textContent=['Wallpaper ◐','Night mode ☾','Sky blue ☀'][n]}
document.getElementById('os-wallpaper').onclick=wallpaper;
function showDesktop(){osWindow.hidden=true;if(paintResizeObserver){paintResizeObserver.disconnect();paintResizeObserver=null}}document.getElementById('os-home').onclick=showDesktop;document.getElementById('minimise-app').onclick=showDesktop;document.getElementById('close-app').onclick=showDesktop;
const appNames={paint:'Doodle pad / absolutely no artistic talent required',notes:'Notes / a spare page',certificates:'My certifications / a gallery of small wins',terminal:'Tiny terminal / browser toy'};
document.querySelectorAll('[data-app]').forEach(b=>b.onclick=()=>openApp(b.dataset.app));
function openApp(name){if(paintResizeObserver){paintResizeObserver.disconnect();paintResizeObserver=null}currentApp=name;osWindow.hidden=false;document.getElementById('window-title').textContent=appNames[name];if(name==='paint')renderPaint();if(name==='notes')renderNotes();if(name==='certificates')renderCertificationApp();if(name==='terminal')renderTerminal()}
function renderNotes(){appContent.innerHTML='<p class="notes-hello">Hello, temporary laptop borrower. ☺</p><p>This is your spare bit of paper. Leave a thought, make a list, or type absolute nonsense.</p><label class="scratch-label" for="os-scratchpad">Your scratchpad · kept only until you reload this page</label><textarea id="os-scratchpad" class="scratchpad" placeholder="Dear internet…" maxlength="5000"></textarea>';const text=document.getElementById('os-scratchpad');text.value=scratchText;text.addEventListener('input',()=>scratchText=text.value)}
let laptopCertificateFilter='all';
function renderCertificationApp(){appContent.innerHTML='<div class="os-cert-intro"><div><h3>My certifications.</h3><p>A small gallery of things I’ve learned. Open a picture to inspect it.</p></div><span class="os-cert-total">11 certificates</span></div><div class="os-cert-filters" aria-label="Laptop certificate filters">'+[['all','All 11'],['foundations','ISC2 & Google'],['cisco','Cisco'],['tryhackme','TryHackMe']].map(([id,label])=>`<button data-os-cert-filter="${id}" aria-pressed="${laptopCertificateFilter===id}">${label}</button>`).join('')+'</div><div class="os-cert-gallery"></div>';renderLaptopCertificates();appContent.querySelectorAll('[data-os-cert-filter]').forEach(b=>b.onclick=()=>{laptopCertificateFilter=b.dataset.osCertFilter;appContent.querySelectorAll('[data-os-cert-filter]').forEach(x=>x.setAttribute('aria-pressed',x===b));renderLaptopCertificates()})}
function renderLaptopCertificates(){const items=certificateData.map((c,i)=>({c,i})).filter(({c})=>laptopCertificateFilter==='all'||c.group===laptopCertificateFilter);const gallery=appContent.querySelector('.os-cert-gallery');gallery.innerHTML=items.map(({c,i})=>`<article class="os-cert-tile"><button class="os-cert-image" data-os-certificate="${i}" aria-label="Inspect ${c.title}"><img src="assets/certificates/${c.slug}.jpg" alt="${c.title} certificate awarded to Fouad Abdulhakeem" loading="lazy"><span>Inspect ↗</span></button><h4><button data-os-certificate="${i}">${c.title}</button></h4><p>${c.issuer}</p><a href="${c.verification}" target="_blank" rel="noopener noreferrer">${c.verificationLabel} ↗</a></article>`).join('');document.querySelector('.os-cert-total').textContent=items.length+' '+(items.length===1?'certificate':'certificates');gallery.querySelectorAll('[data-os-certificate]').forEach(b=>b.onclick=()=>{displayCertificate(Number(b.dataset.osCertificate),items.map(x=>x.i));certificateDialog.showModal()})}
function renderPaint(){appContent.innerHTML='<div class="paint-tools" aria-label="Drawing colours">'+['#2954d8','#15294a','#ef826e','#d2aa38','#5b9b84'].map((c,i)=>`<button class="paint-swatch" style="--swatch:${c}" data-color="${c}" aria-label="${['Blue','Navy','Coral','Gold','Green'][i]} ink" aria-pressed="${paintColor===c}"></button>`).join('')+'<button class="paint-action" id="paint-undo">Undo ↶</button><button class="paint-action" id="paint-clear">Clear page</button></div><div class="paint-canvas-wrap"><canvas id="paint-canvas" aria-label="Doodle canvas. Draw with your mouse or finger."></canvas></div><p class="paint-caption">Draw something wonderfully unnecessary. Mouse or finger, both welcome.</p>';const canvas=document.getElementById('paint-canvas');const ctx=canvas.getContext('2d');function redraw(){const r=canvas.getBoundingClientRect();const dpr=window.devicePixelRatio||1;canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,r.width,r.height);for(const stroke of paintStrokes){ctx.strokeStyle=stroke.color;ctx.fillStyle=stroke.color;ctx.lineWidth=3;ctx.lineCap='round';ctx.lineJoin='round';if(stroke.points.length===1){ctx.beginPath();ctx.arc(stroke.points[0].x*r.width,stroke.points[0].y*r.height,1.5,0,Math.PI*2);ctx.fill()}else{ctx.beginPath();stroke.points.forEach((p,i)=>{if(i===0)ctx.moveTo(p.x*r.width,p.y*r.height);else ctx.lineTo(p.x*r.width,p.y*r.height)});ctx.stroke()}}}function point(e){const r=canvas.getBoundingClientRect();return{x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))}}
canvas.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();if(paintStrokes.length>=1000)paintStrokes.shift();activeStroke={color:paintColor,points:[point(e)],pointer:e.pointerId};paintStrokes.push(activeStroke);canvas.setPointerCapture(e.pointerId);redraw()});canvas.addEventListener('pointermove',e=>{if(!activeStroke||e.pointerId!==activeStroke.pointer)return;if(activeStroke.points.length<5000)activeStroke.points.push(point(e));redraw()});const end=()=>activeStroke=null;canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',end);canvas.addEventListener('lostpointercapture',end);appContent.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{paintColor=b.dataset.color;appContent.querySelectorAll('[data-color]').forEach(s=>s.setAttribute('aria-pressed',s===b))});document.getElementById('paint-undo').onclick=()=>{activeStroke=null;paintStrokes.pop();redraw()};document.getElementById('paint-clear').onclick=()=>{activeStroke=null;paintStrokes=[];redraw()};paintResizeObserver=new ResizeObserver(redraw);paintResizeObserver.observe(canvas.parentElement);requestAnimationFrame(redraw)}
